const listKillsFilteredShip = `-- name: ListKillsFilteredShip :many
WITH cand AS MATERIALIZED (
    SELECT k.killmail_id FROM kills k WHERE k.public AND k.ship_type_id = $11::bigint AND (k.killmail_time, k.killmail_id) < ($12::timestamptz, $13::bigint)
    ORDER BY k.killmail_time DESC, k.killmail_id DESC
    LIMIT $14::bigint
)
SELECT k.killmail_id, k.hash, k.killmail_time, k.system_id, k.region_id, k.location_id, k.victim_character_id, k.victim_corporation_id, k.victim_alliance_id, k.victim_faction_id, k.ship_type_id, k.damage_taken, k.attacker_count, k.fb_character_id, k.fb_corporation_id, k.fb_alliance_id, k.fb_ship_type_id, k.npc, k.solo, k.awox, k.points, k.value_zkill, k.value_ours, k.value_dropped_ours, k.value_coverage, k.priced_at, k.source, k.public, k.ingested_at FROM cand c
JOIN kills k ON k.killmail_id = c.killmail_id
LEFT JOIN sde_systems ss ON ss.system_id = k.system_id
LEFT JOIN sde_types st ON st.type_id = k.ship_type_id
WHERE k.public
  AND COALESCE(k.value_ours, 0) >= $1::double precision
  AND (NOT $2::boolean OR k.solo)
  AND k.attacker_count >= $3::integer
  AND ($4::integer = 0 OR k.attacker_count <= $4::integer)
  AND ($5::bigint = 0 OR k.system_id = $5::bigint)
  AND ($6::bigint = 0 OR k.region_id = $6::bigint)
  AND ($7::bigint = 0 OR k.ship_type_id = $7::bigint)
  AND ($8::bigint = 0 OR st.group_id = $8::bigint)
  AND ($9::text = '' OR CASE WHEN k.system_id >= 32000000 THEN 'abyssal'
                WHEN k.system_id >= 31000000 THEN 'wh'
                WHEN k.region_id = 10000070 THEN 'pochven'
                WHEN COALESCE(ss.security, 0) >= 0.45 THEN 'high'
                WHEN COALESCE(ss.security, 0) > 0 THEN 'low'
                ELSE 'null' END = $9::text)
ORDER BY k.killmail_time DESC, k.killmail_id DESC
LIMIT $10::bigint
`

